use super::ProcedureSnapshot;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->ProcedureSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let s=&f["snapshot"];let f=&s["flow"];let ft=&f["target"];let fd=&ft["dialect"];let t=&s["text"];let tt=&t["target"];let td=&tt["dialect"];ProcedureSnapshot{schema:s["schema"].as_str().unwrap().into(),flow:store::ArtifactChild::new(f["childId"].as_str().unwrap().into(),store::os_io::ArtifactRef{artifact_id:ft["artifactId"].as_str().unwrap().into(),dialect:store::os_io::ArtifactDialect{artifact_kind:fd["artifactKind"].as_str().unwrap().into(),standard:fd["standard"].as_str().unwrap().into(),subset:fd["subset"].as_str().unwrap().into()}}),text:store::ArtifactChild::new(t["childId"].as_str().unwrap().into(),store::os_io::ArtifactRef{artifact_id:tt["artifactId"].as_str().unwrap().into(),dialect:store::os_io::ArtifactDialect{artifact_kind:td["artifactKind"].as_str().unwrap().into(),standard:td["standard"].as_str().unwrap().into(),subset:td["subset"].as_str().unwrap().into()}})}}
fn project(s:&ProcedureSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<ProcedureSnapshot,String>{ProcedureSnapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]fn sqlite_snapshot_procedure_independent_sqlite_queries_and_owned_edit(){use std::io::Write;use std::process::{Command,Stdio};let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const n=d.query('SELECT child_id,artifact_id FROM procedure_text_child').get();if(n.child_id===n.artifact_id)throw Error('distinct target');d.query(\"UPDATE procedure_document SET schema_id='independent procedure schema 日本'\").run();d.query(\"UPDATE procedure_text_child SET artifact_id='independent seed target β'\").run();await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let back=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(back.schema,"independent procedure schema 日本");assert_eq!(back.text.target.artifact_id,"independent seed target β");assert_eq!(back.text.child_id,s.text.child_id);assert_eq!(back.flow,s.flow);}
#[test]fn sqlite_snapshot_procedure_bad_owned_rows_and_bounded_cancellation(){let d=project(&fixture());for case in 0..5{let mut bad=d.clone();match case{0=>bad.table_mut("procedure_text_child").unwrap().rows.clear(),1=>bad.table_mut("procedure_flow_child").unwrap().rows[0].values[0]=SqliteValue::Integer(2),2=>bad.table_mut("procedure_document").unwrap().rows[0].values[1]=SqliteValue::Blob(vec![0]),3=>bad.table_mut("procedure_text_child").unwrap().rows[0].values[5]=SqliteValue::Blob(vec![0]),_=>bad.table_mut("procedure_document").unwrap().sql=bad.table("procedure_document").unwrap().sql.replace("schema_id TEXT NOT NULL","schema_id TEXT")};assert!(restore(&bad).is_err());}assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()})).is_err());assert!(ProcedureSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());let mut large=fixture();large.schema="文".repeat(40000);assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut|p|p.completed==0,SqliteDatabaseLimits::default())).is_err());}
#[test]fn sqlite_snapshot_procedure_owned_parent_and_child_handles(){let s=fixture();let d=project(&s);assert_eq!(d.tables.len(),3);let back=restore(&import_sqlite_database(&export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(back,s);assert_ne!(back.flow.child_id,back.flow.target.artifact_id);assert_ne!(back.text.child_id,back.text.target.artifact_id);}

#[test]fn sqlite_snapshot_procedure_exact_three_domain_rows_need_no_metadata_reservation(){let s=fixture();let d=s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:3,..SqliteDatabaseLimits::default()})).unwrap();assert_eq!(d.tables.iter().map(|t|t.rows.len()).sum::<usize>(),3);assert_eq!(ProcedureSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:3,..SqliteDatabaseLimits::default()})).unwrap(),s);}

#[test]
fn sqlite_snapshot_procedure_bare_erased_encodings_and_coordinate_refusals(){
 let source=fixture();let provider=store::ArtifactCodec::bare::<ProcedureSnapshot,crate::ProcedureMutation>(crate::PROCEDURE_DOCUMENT_SCHEMA).snapshot_sqlite.unwrap();assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<ProcedureSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.imperative.procedure".into(),standard:"1".into(),subset:"*".into()};
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<ProcedureSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<ProcedureSnapshot as store::ArtifactDsl>::print_dsl(&source))};let database=(provider.export)(crate::PROCEDURE_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(restore(&database).unwrap(),source);let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let imported=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!((provider.import)(crate::PROCEDURE_DOCUMENT_SCHEMA,&dialect,imported,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value,payload);assert!((provider.import)(crate::PROCEDURE_DOCUMENT_SCHEMA,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative,SqliteDatabaseLimits::default())).is_err());}
 let database=project(&source);for(artifact_kind,standard,subset)in[("s.imperative.other","1","*"),("s.imperative.procedure","v1","*"),("s.imperative.procedure","1","other")]{let wrong=store::os_io::ArtifactDialect{artifact_kind:artifact_kind.into(),standard:standard.into(),subset:subset.into()};assert!(source.validate_sqlite_snapshot_subset(&wrong,&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_procedure_actual_declaration_typed_io_and_final_metadata_rows(){
 use semio_framework_os_kernel::io::io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot};
 semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("imperative").label("Procedure SQLite declaration").version("0.0.1").package_id("semio:imperative").artifact(crate::declaration().unwrap()).try_build().unwrap();let source=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.imperative.procedure".into(),standard:"1".into(),subset:"*".into()};
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect,&source,encoding,SqliteDatabaseLimits{max_rows:4,..SqliteDatabaseLimits::default()},&mut |p|{phases.push(p.phase);true}).await.unwrap().value;let database=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(database.tables.iter().map(|t|t.rows.len()).sum::<usize>(),4);let restored=io_import_sqlite_snapshot::<ProcedureSnapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;assert_eq!(restored,source);assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::DecodeNative|SqliteSnapshotPhase::EncodeNative)));assert!(io_export_sqlite_snapshot(&dialect,&source,encoding,SqliteDatabaseLimits{max_rows:3,..SqliteDatabaseLimits::default()},&mut |_|true).await.is_err());}
}

